/**
 * The CLI commands agents may run, for MCP servers that cannot load the CLI's
 * route tree (the hosted server on Workers).
 *
 * `command-catalog.json` is generated by the CLI (`generate:command-catalog`
 * in `packages/cli`) from its route tree's introspection (`lib/introspect.ts`).
 * Do not edit it by hand.
 */

import commandCatalogData from "./command-catalog.json";

/** Where agents may run a command; hidden commands are left out. */
type CommandExposure = "exposed" | "stdio-only";

/**
 * What a command may do to Sentry, or `method` when each call takes the class
 * of the HTTP method it sends (`sentry api --method`).
 */
type CommandPermission = "read" | "write" | "destructive" | "method";

/** The subset of JSON Schema (2020-12) the catalog uses. */
export type JsonSchema = {
  type?: "string" | "number" | "boolean" | "array" | "object";
  title?: string;
  description?: string;
  enum?: string[];
  /** Suggested values; others are accepted too. */
  examples?: string[];
  default?: unknown;
  items?: JsonSchema | false;
  prefixItems?: JsonSchema[];
  minItems?: number;
  properties?: Record<string, JsonSchema>;
  required?: string[];
  additionalProperties?: false;
};

/** A field of a command's `--json` output. */
type CommandOutputField = {
  name: string;
  type: string;
  optional: boolean;
  description?: string;
};

/** A `@sentry/api` function the command calls. */
type CommandApiOperation = {
  fn: string;
  note?: string;
};

export type CommandCatalogEntry = {
  /** Full command path, such as `sentry issue list`. */
  path: string;
  brief: string;
  permission: CommandPermission;
  exposure: CommandExposure;
  /**
   * The command's arguments: `positional` (the positional arguments in
   * order) and `flags` (by flag name, without `--`).
   */
  parameters: JsonSchema;
  /** Completion kind of each positional and flag that has one. */
  completions?: {
    /** By position; a variadic positional has one entry for every word. */
    positional?: (string | null)[];
    flags?: Record<string, string>;
  };
  /** Flags that take a path on the local machine, which only stdio can serve. */
  localPathFlags?: string[];
  /** Each example is a `# description` line followed by its commands. */
  examples: string[];
  outputFields?: CommandOutputField[];
  apiOperations: CommandApiOperation[];
};

export type CommandCatalog = {
  /** Sorted by path. */
  commands: CommandCatalogEntry[];
};

// Through `unknown`: TypeScript types the JSON's flag maps as one union in which
// each command lacks the others' flags, and `undefined` fails the index
// signature of `JsonSchema.properties`.
export const commandCatalog = commandCatalogData as unknown as CommandCatalog;
